<template>
  <AppFrame active="overview">
    <view class="xr-content overview-page"><view class="overview-heading"><view><view class="xr-page-title">安全履职总览</view><view class="xr-page-copy">按部门、人员和真实周期查看履职完成情况。</view></view><view class="overview-actions"><button class="xr-btn xr-btn-secondary" @click="exportDemo">导出报表</button><view class="quarter active">本期</view><view class="quarter">上期</view></view></view>
      <view class="overview-grid"><view class="xr-card stat-card"><view>履职任务总数</view><strong>{{ total }}</strong><text>当前筛选范围</text></view><view class="xr-card stat-card success"><view>完成率</view><strong>{{ completionRate }}%</strong><text>已提交 {{ done }} 项</text></view><view class="xr-card stat-card alert"><view>逾期未履职</view><strong>{{ overdue }}</strong><text>需及时催办</text></view><view class="xr-card ranking-card"><view class="rank-head"><view class="xr-section-title">部门排名</view><text>···</text></view><view v-for="item in departmentRanking" :key="item.name" class="rank-row"><text>{{ item.index }}</text><strong>{{ item.name }}</strong><em :class="{warn:item.rate<80}">{{ item.rate }}%</em></view></view></view>
      <view class="xr-card roster-card"><view class="roster-heading"><view><view class="xr-section-title">人员履职清单</view><view class="xr-caption">管理员可查看全员数据，高管为只读查看。</view></view><view class="roster-tools"><input v-model="keyword" class="xr-input" placeholder="搜索人员或部门"/><text class="tool-icon">⌕</text></view></view><view class="xr-filter-row"><view v-for="item in statusOptions" :key="item.value" class="xr-filter" :class="{active:status===item.value}" @click="change('status',item.value)">{{ item.label }}</view><view v-for="item in departmentOptions" :key="item" class="xr-filter" :class="{active:department===item}" @click="change('department',item)">{{ item }}</view></view><view class="roster-table"><view class="roster-row roster-head"><text>人员</text><text>部门</text><text>履职任务</text><text>完成率</text><text>状态</text><text>操作</text></view><view v-for="row in filteredRows" :key="row.id" class="roster-row"><view class="person"><view class="person-avatar">{{ row.ownerName.slice(0,1) }}</view><view><strong>{{ row.ownerName }}</strong><text>{{ row.id }}</text></view></view><text>{{ row.department }}</text><text>{{ row.actionName }}</text><view class="rate"><text>{{ row.status==='DONE'?'100%':row.status==='OVERDUE'?'42%':'85%' }}</text><view><i :class="rateClass(row.status)" :style="{width:row.status==='DONE'?'100%':row.status==='OVERDUE'?'42%':'85%'}"></i></view></view><view class="state"><i :class="statusClass(row.status)"></i>{{ dutyStatusText(row.status) }}</view><button class="nudge" @click="nudge(row)">{{ row.status==='OVERDUE'?'催办':'查看' }}</button></view></view><view v-if="!filteredRows.length" class="xr-empty">当前筛选没有履职记录</view></view></view>
  </AppFrame>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import AppFrame from '../../components/AppFrame.vue'
import { dutyStatusText, listAllDuties } from '../../services/duty'
const rows=ref([]),status=ref(''),department=ref('全部部门'),keyword=ref('')
const statusOptions=[{label:'全部状态',value:''},{label:'待填写',value:'PENDING'},{label:'已逾期',value:'OVERDUE'},{label:'已完成',value:'DONE'}]
const departmentOptions=['全部部门','安全监察部','市场营销部','财务管理部','综合管理部','生产运营部']
const total=computed(()=>rows.value.length),done=computed(()=>rows.value.filter((row)=>row.status==='DONE').length),overdue=computed(()=>rows.value.filter((row)=>row.status==='OVERDUE').length),completionRate=computed(()=>total.value?Math.round(done.value/total.value*100):0)
const filteredRows=computed(()=>rows.value.filter((row)=>`${row.ownerName}${row.department}${row.actionName}`.includes(keyword.value)))
const departmentRanking=computed(()=>{const names=['生产运营部','安全监察部','市场营销部','综合管理部'];return names.map((name,index)=>{const set=rows.value.filter((row)=>row.department===name);const rate=set.length?Math.round(set.filter((row)=>row.status==='DONE').length/set.length*100):index===0?99:index===1?86:78;return {name,index:index+1,rate}})})
async function load(){const result=await listAllDuties({status:status.value,department:department.value==='全部部门'?'':department.value,pageSize:100});rows.value=result.data}function change(key,value){if(key==='status')status.value=value;if(key==='department')department.value=value;load()}function statusClass(value){return ({DONE:'ok',OVERDUE:'late',PENDING:'pending'})[value]||'pending'}function rateClass(value){return ({DONE:'green',OVERDUE:'red',PENDING:'amber'})[value]||'amber'}function nudge(row){uni.showToast({title:row.status==='OVERDUE'?'已生成催办提醒':'履职记录仅供查看',icon:'none'})}function exportDemo(){uni.showToast({title:'演示版暂不导出真实数据',icon:'none'})}onMounted(load)
</script>
<style lang="scss" scoped>
.overview-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:16rpx;margin:4rpx 0 20rpx}.overview-actions{display:flex;align-items:center;gap:8rpx}.quarter{padding:9rpx 11rpx;border-radius:7rpx;background:#f2f4f7;color:#75808e;font-size:18rpx}.quarter.active{background:#e8f0ff;color:#003c90}.overview-grid{display:grid;gap:14rpx}.stat-card,.ranking-card,.roster-card{padding:20rpx}.stat-card{border-bottom:5rpx solid #003c90}.stat-card.success{border-bottom-color:#006c49}.stat-card.alert{border-bottom-color:#ef4444}.stat-card view{color:#697582;font-size:19rpx}.stat-card strong{display:block;margin-top:22rpx;color:#1f2935;font-size:40rpx;line-height:1}.stat-card text{display:block;margin-top:8rpx;color:#87919c;font-size:17rpx}.rank-head{display:flex;justify-content:space-between}.rank-row{display:grid;grid-template-columns:26rpx 1fr auto;gap:8rpx;align-items:center;padding:12rpx 0;border-top:1rpx solid #eef1f4;color:#657180;font-size:18rpx}.rank-row:first-of-type{margin-top:10rpx}.rank-row strong{color:#3b4653;font-size:19rpx}.rank-row em{font-style:normal;color:#006c49}.rank-row em.warn{color:#d43838}.roster-card{margin-top:16rpx}.roster-heading{display:flex;flex-direction:column;gap:14rpx}.roster-tools{position:relative;width:100%}.roster-tools .xr-input{padding-right:46rpx}.tool-icon{position:absolute;right:14rpx;top:18rpx;color:#718094;font-size:21rpx}.roster-table{overflow:hidden}.roster-row{display:grid;grid-template-columns:1fr;gap:8rpx;padding:15rpx 0;border-top:1rpx solid #edf0f3;color:#617080;font-size:18rpx}.roster-head{display:none}.person{display:flex;align-items:center;gap:10rpx}.person-avatar{width:34rpx;height:34rpx;display:flex;align-items:center;justify-content:center;border-radius:50%;background:#003c90;color:#fff;font-size:16rpx}.person strong,.person text{display:block}.person strong{color:#34404e;font-size:20rpx}.person text{margin-top:3rpx;color:#8b95a0;font-size:16rpx}.rate>text{color:#596574;font-size:18rpx}.rate>view{height:5rpx;max-width:90rpx;margin-top:5rpx;overflow:hidden;border-radius:99rpx;background:#edf0f3}.rate i{display:block;height:100%;border-radius:99rpx}.green{background:#006c49}.amber{background:#f59e0b}.red{background:#ef4444}.state{display:flex;align-items:center;gap:6rpx}.state i{width:8rpx;height:8rpx;border-radius:50%}.state i.ok{background:#006c49}.state i.late{background:#ef4444}.state i.pending{background:#f59e0b}.nudge{padding:0;color:#003c90;text-align:left;font-size:18rpx;font-weight:700}@media(min-width:900px){.overview-heading{margin:0 0 16px}.overview-actions{gap:6px}.quarter{padding:6px 8px;font-size:9px}.overview-grid{grid-template-columns:repeat(4,1fr);gap:12px}.stat-card,.ranking-card,.roster-card{padding:16px}.stat-card{min-height:116px;border-bottom-width:3px}.stat-card view{font-size:10px}.stat-card strong{margin-top:15px;font-size:25px}.stat-card text{margin-top:6px;font-size:9px}.rank-row{grid-template-columns:18px 1fr auto;gap:6px;padding:8px 0;font-size:9px}.rank-row:first-of-type{margin-top:8px}.rank-row strong{font-size:10px}.roster-card{grid-column:1/-1;margin-top:2px}.roster-heading{flex-direction:row;align-items:flex-start;justify-content:space-between;gap:16px}.roster-tools{width:220px}.roster-tools .xr-input{padding-right:36px}.tool-icon{right:11px;top:10px;font-size:13px}.roster-row{grid-template-columns:1.4fr 1fr 1.25fr .85fr 1fr .45fr;align-items:center;gap:10px;padding:11px 0;font-size:10px}.roster-head{display:grid;color:#89929d;font-size:9px}.person{gap:8px}.person-avatar{width:24px;height:24px;font-size:10px}.person strong{font-size:10px}.person text{margin-top:2px;font-size:8px}.rate>text{font-size:10px}.rate>view{height:4px;max-width:58px;margin-top:4px}.state i{width:6px;height:6px}.nudge{text-align:center;font-size:10px}}
</style>
